function record=runV4BCalibrationCandidate(candidateIndex)
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();list=v4BCalibrationCandidates();p=list(candidateIndex);schedule=v4ContinuousPassSchedule(c);eligible=find(schedule.metricEligible);neg=eligible(schedule.frameCenterTimeSec(eligible)<0);pos=eligible(schedule.frameCenterTimeSec(eligible)>0);target=sort([neg(1:8);neg(end-7:end);pos(1:8);pos(end-7:end)]);state=struct('time',schedule.passStartTimeSec,'phase',0,'cross',struct());accepted=0;falseVp=0;sse=0;count=0;exceed=0;
for fi=1:schedule.frameCount,ledger=v4RandomLedger(c,'validation',9,1,fi);frame=v4GenerateContinuousFrame(c,state.time,-21,ledger,state.phase,'AWGN');state.time=frame.nextFrameStartTimeSec;state.phase=frame.nextFrameStartPhaseRad;if ~schedule.metricEligible(fi),state.cross=struct();continue,end;b=v4CommonBootstrap(frame.observation.rxPhysical(1:8,:),c,SearchStepBins=p.searchStepBins);robust=v4BIndividualPreambleRate(frame.observation.rxPhysical(1:8,:),c,p.searchStepBins);measurement=schedule.frameStartTimeSec(fi)+4*c.symbolDurationSec;[rate,state.cross]=v4CrossFrameRateUpdate(state.cross,measurement,mean(b.cfoBins),robust.rateBinsPerSec,c,p);if ~ismember(fi,target),continue,end;rx=v4Stage55Decode(frame.observation,b,c,p,CrossFrameRateBinsPerSec=rate,CrossFrameHistoryCount=state.cross.historyCount);m=v4EvaluateFrame(rx,frame.truth,c);mask=rx.virtualPilotAccepted;accepted=accepted+sum(mask);falseVp=falseVp+sum(mask&rx.detectedPhysicalBins~=frame.truth.payloadPhysicalBins);err=rx.estimatedCfoBins-frame.truth.dataCfoBins;sse=sse+sum(err.^2);count=count+112;exceed=exceed+sum(abs(err)>=0.5);end
if accepted>0,fa=falseVp/accepted;else,fa=NaN;end;coverage=accepted/(32*112);record=struct('candidateIndex',candidateIndex,'frames',32,'vpAccepted',accepted,'vpFalse',falseVp,'falseAcceptance',fa,'coverage',coverage,'cfoRmseBins',sqrt(sse/count),'halfBinExceedance',exceed/count,'passed',isfinite(fa)&&fa<=0.02&&coverage>=0.01);folder=fullfile(root,'results','calibration','track_b','B-param-v01','candidates');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,sprintf('candidate_%02d.mat',candidateIndex)),'record','p','-v7.3');write(fullfile(folder,sprintf('candidate_%02d.json',candidateIndex)),jsonencode(record,'PrettyPrint',true));fprintf('candidate %d accepted=%d false=%d coverage=%.4f rmse=%.4f\n',candidateIndex,accepted,falseVp,coverage,record.cfoRmseBins);
end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
